from robot.utils.robottime import timestr_to_secs

from .base import BaseInterface
from ..util import wrap_result
from ..validators import IsString


class CertificateManagmentInterface(BaseInterface):

    def get_certificate_file(self, fingerprint, target_file_name, timeout=60, alias="default"):
        """Get certificate file.

        :param string fingerprint: Unique sign of certificate.
        :param string target_file_name: target certificate filename.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        IsString().check(fingerprint)
        timeout = timestr_to_secs(timeout)
        self.store.get(alias).execute_customer_procedure_then_infomodel_request(
            "getCertFile", {"fingerprint": fingerprint}, timeout, output_file_name=target_file_name)

    def get_certificate_details(self, fingerprint, timeout=60, alias="default"):
        """Get certificate details.

        :param string fingerprint: Unique sign of certificate.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        IsString().check(fingerprint)
        timeout = timestr_to_secs(timeout)
        return self.store.get(alias).execute_customer_procedure_then_infomodel_request(
            "getCertDetails", {"fingerPrint": fingerprint}, timeout)

    @wrap_result
    def get_certificate_list(self, type, timeout=60, alias="default"):
        """Get certificate list.

        :param string type: Certificate type (BTS, TA, CA, RA, Vendor or All)
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        IsString().check(type)

        timeout = timestr_to_secs(timeout)
        return self.store.get(alias).execute_customer_procedure_then_infomodel_request(
            "getCertList", {"type": type}, timeout)

    @wrap_result
    def get_certificate_revocation_list(self, timeout=60, alias="default"):
        """Get certificate revocation list.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        return self.store.get(alias).execute_customer_procedure_then_infomodel_request(
            "certGetRevocationList", {}, timeout)

    def cmp_update_key(self, timeout=60, alias="default"):
        """CMP update key.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        self.store.get(alias).execute_customer_procedure_then_old_procedure("certCmpKeyUpdate", {}, timeout)

    def install_certificate(self, cert_file, cert_type, cert_format, password=None, timeout=60, alias="default"):
        """Install certificate.

        :param string cert_file: Certificate file path.
        :param string cert_type: Certificate type (BtsTrustChain or AdditionalCa)
        :param string cert_format: Certificate format (PEM, P12 or DER)
        :param string password: Certificate password.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        IsString().check(cert_file)
        IsString().check(cert_type)
        IsString().check(cert_format)

        timeout = timestr_to_secs(timeout)

        parameters = {"fileType": cert_type, "fileFormat": cert_format}
        if password:
            parameters["password"] = password
        self.store.get(alias).execute_customer_procedure_then_old_procedure(
            "installCert", parameters, timeout, input_file_name=cert_file)

    def delete_certificate(self, fingerprint, timeout=60, alias="default"):
        """Delete certificate.

        :param string fingerprint: Unique sign of certificate.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        IsString().check(fingerprint)

        timeout = timestr_to_secs(timeout)
        self.store.get(alias).execute_customer_procedure_then_old_procedure(
            "deleteCert", {"fingerPrint": fingerprint}, timeout)

    def restore_vendor_certificate(self, timeout=60, alias="default"):
        """Restore vendor certificate.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        self.store.get(alias).execute_customer_procedure_then_old_procedure("certRestoreVendor", {}, timeout)

    def update_certificate_revocation_list(self, timeout=60, alias="default"):
        """Update certificate revocation list.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        self.store.get(alias).execute_customer_procedure_then_old_procedure("certUpdateRevocationList", {}, timeout)

    def set_certificate_automatic_managment(self, reference_number, preshared_key, timeout=60, alias="default"):
        """Set certificate automatic managment.

        :param string reference_number: Reference number
        :param string preshared_key: Pre-shared key.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        IsString().check(reference_number)
        IsString().check(preshared_key)

        timeout = timestr_to_secs(timeout)
        self.store.get(alias).execute_customer_procedure_then_old_procedure(
            "certAutomaticManagement", {"referenceNumber": reference_number, "preSharedKey": preshared_key}, timeout)

    def cmp_initialize_certificate(self, timeout=60, alias="default"):
        """CMP initialize certificate.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """

        timeout = timestr_to_secs(timeout)
        self.store.get(alias).execute_customer_procedure_then_old_procedure("cmpInitializeCertificate", {}, timeout)
